INSERT IGNORE INTO aprendizaje_version_actividad
(id, actividad_id, numero_version, titulo, instrucciones, idioma, dificultad, minutos_estimados, estado, publicado_en) VALUES
('e4020000-0000-4000-8000-000000000001', 'e4010000-0000-4000-8000-000000000001', 1, 'Las alpacas de la abuela Rosa', 'Reto de razonamiento lógico. La abuela Rosa cuida alpacas en Puno. Lee cada situación, piensa con calma y elige tu respuesta.', 'es-PE', 1, 5, 'PUBLICADO', UTC_TIMESTAMP(6)),
('e4020000-0000-4000-8000-000000000002', 'e4010000-0000-4000-8000-000000000002', 1, 'Panes calientitos en la panadería', 'Reto de razonamiento lógico. Don Lucho hornea panes para el barrio. Cuenta con cuidado y elige tu respuesta.', 'es-PE', 1, 5, 'PUBLICADO', UTC_TIMESTAMP(6)),
('e4020000-0000-4000-8000-000000000003', 'e4010000-0000-4000-8000-000000000003', 1, 'Mateo y su cometa', 'Reto de comprensión lectora. Lee el texto con calma. Puedes escucharlo las veces que quieras y luego responde.', 'es-PE', 1, 5, 'PUBLICADO', UTC_TIMESTAMP(6)),
('e4020000-0000-4000-8000-000000000004', 'e4010000-0000-4000-8000-000000000004', 1, 'La lonchera de Killa', 'Reto de comprensión lectora. Lee el texto con calma. Puedes escucharlo las veces que quieras y luego responde.', 'es-PE', 1, 5, 'PUBLICADO', UTC_TIMESTAMP(6)),
('e4020000-0000-4000-8000-000000000005', 'e4010000-0000-4000-8000-000000000005', 1, 'Compras en la feria de Huancayo', 'Reto de razonamiento lógico. Es domingo de feria en Huancayo. Resuelve cada situación y elige tu respuesta.', 'es-PE', 2, 5, 'PUBLICADO', UTC_TIMESTAMP(6)),
('e4020000-0000-4000-8000-000000000006', 'e4010000-0000-4000-8000-000000000006', 1, 'La fila para subir a la combi', 'Reto de razonamiento lógico. Ordena las pistas en tu mente o en tu cuaderno y elige tu respuesta.', 'es-PE', 2, 5, 'PUBLICADO', UTC_TIMESTAMP(6)),
('e4020000-0000-4000-8000-000000000007', 'e4010000-0000-4000-8000-000000000007', 1, 'El colibrí y las flores', 'Reto de comprensión lectora. Lee el texto con calma. Puedes escucharlo las veces que quieras y luego responde.', 'es-PE', 2, 5, 'PUBLICADO', UTC_TIMESTAMP(6)),
('e4020000-0000-4000-8000-000000000008', 'e4010000-0000-4000-8000-000000000008', 1, 'La minga del barrio', 'Reto de comprensión lectora. Lee el texto con calma. Puedes escucharlo las veces que quieras y luego responde.', 'es-PE', 2, 5, 'PUBLICADO', UTC_TIMESTAMP(6)),
('e4020000-0000-4000-8000-000000000009', 'e4010000-0000-4000-8000-000000000009', 1, 'De viaje por la Panamericana Sur', 'Reto de razonamiento lógico. Una familia viaja de Lima a Nasca. Resuelve cada situación y elige tu respuesta.', 'es-PE', 3, 5, 'PUBLICADO', UTC_TIMESTAMP(6)),
('e4020000-0000-4000-8000-000000000010', 'e4010000-0000-4000-8000-000000000010', 1, 'La chacra de quinua', 'Reto de razonamiento lógico. En una comunidad de Puno se siembra quinua. Piensa paso a paso y elige tu respuesta.', 'es-PE', 3, 5, 'PUBLICADO', UTC_TIMESTAMP(6)),
('e4020000-0000-4000-8000-000000000011', 'e4010000-0000-4000-8000-000000000011', 1, 'Las islas flotantes del Titicaca', 'Reto de comprensión lectora. Lee el texto con calma. Puedes escucharlo las veces que quieras y luego responde.', 'es-PE', 3, 5, 'PUBLICADO', UTC_TIMESTAMP(6)),
('e4020000-0000-4000-8000-000000000012', 'e4010000-0000-4000-8000-000000000012', 1, 'Una carta desde Iquitos', 'Reto de comprensión lectora. Lee el texto con calma. Puedes escucharlo las veces que quieras y luego responde.', 'es-PE', 3, 5, 'PUBLICADO', UTC_TIMESTAMP(6));
INSERT IGNORE INTO aprendizaje_bloque_contenido
(id, version_actividad_id, numero_secuencia, tipo, texto_cuerpo, texto_accesibilidad) VALUES
('e4030000-0000-4000-8000-000000000003', 'e4020000-0000-4000-8000-000000000003', 1, 'TEXTO', 'En agosto, Mateo vuela su cometa en la playa de Pimentel. Su cometa es roja y tiene una cola larga con lazos amarillos. Cuando sopla el viento, la cometa sube muy alto. Mateo ríe y su hermana Lucía aplaude.', 'Lectura del reto: Mateo y su cometa'),
('e4030000-0000-4000-8000-000000000004', 'e4020000-0000-4000-8000-000000000004', 1, 'TEXTO', 'Killa prepara su lonchera con su mamá. Ponen una mandarina, un pan con queso y agua hervida. Killa no lleva gaseosa porque quiere estar fuerte para jugar en el recreo.', 'Lectura del reto: La lonchera de Killa'),
('e4030000-0000-4000-8000-000000000007', 'e4020000-0000-4000-8000-000000000007', 1, 'TEXTO', 'El colibrí es un ave muy pequeña que vive en muchas regiones del Perú. Mueve sus alas tan rápido que parece quedarse quieto en el aire. Se alimenta del néctar de las flores y, al ir de flor en flor, lleva polen de una a otra. Así ayuda a que nazcan nuevas plantas.', 'Lectura del reto: El colibrí y las flores'),
('e4030000-0000-4000-8000-000000000008', 'e4020000-0000-4000-8000-000000000008', 1, 'TEXTO', 'El sábado, los vecinos del barrio hicieron una minga para limpiar el parque. Unos recogieron basura, otros pintaron las bancas y los niños sembraron plantas. Al final, compartieron una olla común. Todos estaban cansados, pero contentos de ver su parque bonito.', 'Lectura del reto: La minga del barrio'),
('e4030000-0000-4000-8000-000000000011', 'e4020000-0000-4000-8000-000000000011', 1, 'TEXTO', 'El lago Titicaca está entre Perú y Bolivia, a más de 3800 metros sobre el nivel del mar. Es uno de los lagos navegables más altos del mundo. En sus aguas viven los uros, que construyen islas flotantes con la totora, una planta que crece en el lago. Con la totora también fabrican sus casas y sus botes.', 'Lectura del reto: Las islas flotantes del Titicaca'),
('e4030000-0000-4000-8000-000000000012', 'e4020000-0000-4000-8000-000000000012', 1, 'TEXTO', 'Querida prima: te escribo desde Iquitos. Ayer navegamos por el río Amazonas en un bote y vimos delfines rosados. El guía nos explicó que debemos cuidar el río y no botar basura, porque los delfines y los peces viven allí. Te extraño mucho. Con cariño, Daniela.', 'Lectura del reto: Una carta desde Iquitos');
INSERT IGNORE INTO evaluacion_pregunta
(id, version_actividad_id, numero_secuencia, tipo, enunciado, explicacion, puntos) VALUES
('e4040000-0000-4000-8000-000000000101', 'e4020000-0000-4000-8000-000000000001', 1, 'OPCION_UNICA', 'La abuela Rosa tiene 3 alpacas blancas y 4 alpacas marrones. ¿Cuántas alpacas tiene en total?', 'Juntamos las blancas y las marrones: 3 + 4 = 7 alpacas.', 1),
('e4040000-0000-4000-8000-000000000102', 'e4020000-0000-4000-8000-000000000001', 2, 'OPCION_UNICA', 'En el corral van en fila: alpaca, llama, alpaca, llama, alpaca… ¿Qué animal sigue?', 'El patrón se repite: alpaca, llama. Después de una alpaca viene una llama.', 1),
('e4040000-0000-4000-8000-000000000201', 'e4020000-0000-4000-8000-000000000002', 1, 'OPCION_UNICA', 'Don Lucho cuenta los panes de 2 en 2: 2, 4, 6, 8… ¿Qué número sigue?', 'Cada vez sumamos 2: 8 + 2 = 10.', 1),
('e4040000-0000-4000-8000-000000000202', 'e4020000-0000-4000-8000-000000000002', 2, 'OPCION_UNICA', 'Hay 10 panes en la canasta y Ana compra 3. ¿Cuántos panes quedan?', 'Quitamos los panes que compró Ana: 10 − 3 = 7 panes.', 1),
('e4040000-0000-4000-8000-000000000301', 'e4020000-0000-4000-8000-000000000003', 1, 'OPCION_UNICA', '¿Dónde vuela Mateo su cometa?', 'El texto dice: «Mateo vuela su cometa en la playa de Pimentel».', 1),
('e4040000-0000-4000-8000-000000000302', 'e4020000-0000-4000-8000-000000000003', 2, 'OPCION_UNICA', '¿De qué color es la cometa de Mateo?', 'La cometa es roja. Los lazos de la cola son los amarillos.', 1),
('e4040000-0000-4000-8000-000000000401', 'e4020000-0000-4000-8000-000000000004', 1, 'OPCION_UNICA', '¿Qué bebida lleva Killa en su lonchera?', 'El texto dice que ponen agua hervida en la lonchera.', 1),
('e4040000-0000-4000-8000-000000000402', 'e4020000-0000-4000-8000-000000000004', 2, 'OPCION_UNICA', '¿Por qué Killa no lleva gaseosa?', 'El texto explica que quiere estar fuerte para jugar en el recreo.', 1),
('e4040000-0000-4000-8000-000000000501', 'e4020000-0000-4000-8000-000000000005', 1, 'OPCION_UNICA', 'En la feria, un choclo cuesta S/ 2. ¿Cuánto pagas por 4 choclos?', 'Son 4 choclos de S/ 2 cada uno: 4 × 2 = S/ 8.', 1),
('e4040000-0000-4000-8000-000000000502', 'e4020000-0000-4000-8000-000000000005', 2, 'OPCION_UNICA', 'Pagas los 4 choclos con un billete de S/ 10. ¿Cuánto vuelto recibes?', 'Al billete le quitamos lo que pagaste: 10 − 8 = S/ 2 de vuelto.', 1),
('e4040000-0000-4000-8000-000000000601', 'e4020000-0000-4000-8000-000000000006', 1, 'OPCION_UNICA', 'Ana está delante de Bruno y Carla está detrás de Bruno. ¿Quién está en el medio?', 'El orden es Ana, Bruno y Carla. Bruno queda en el medio.', 1),
('e4040000-0000-4000-8000-000000000602', 'e4020000-0000-4000-8000-000000000006', 2, 'OPCION_UNICA', 'La combi sale cada 15 minutos. Si salió a las 7:00, ¿a qué hora sale la siguiente?', 'Sumamos 15 minutos a las 7:00 y obtenemos las 7:15.', 1),
('e4040000-0000-4000-8000-000000000701', 'e4020000-0000-4000-8000-000000000007', 1, 'OPCION_UNICA', 'Según el texto, ¿de qué se alimenta el colibrí?', 'El texto dice que el colibrí «se alimenta del néctar de las flores».', 1),
('e4040000-0000-4000-8000-000000000702', 'e4020000-0000-4000-8000-000000000007', 2, 'OPCION_UNICA', '¿Cómo ayuda el colibrí a las plantas?', 'Al ir de flor en flor lleva polen, y así ayuda a que nazcan nuevas plantas.', 1),
('e4040000-0000-4000-8000-000000000801', 'e4020000-0000-4000-8000-000000000008', 1, 'OPCION_UNICA', '¿Qué hicieron los niños durante la minga?', 'El texto dice que «los niños sembraron plantas».', 1),
('e4040000-0000-4000-8000-000000000802', 'e4020000-0000-4000-8000-000000000008', 2, 'OPCION_UNICA', '¿Cuál es la idea principal del texto?', 'Todo el texto cuenta cómo los vecinos se organizaron para limpiar y mejorar su parque.', 1),
('e4040000-0000-4000-8000-000000000901', 'e4020000-0000-4000-8000-000000000009', 1, 'OPCION_UNICA', 'Un bus sale de Lima a las 6:00 p. m. y llega a Nasca 7 horas después. ¿A qué hora llega?', 'De 6:00 p. m. a 12:00 a. m. pasan 6 horas; una hora más es la 1:00 a. m.', 1),
('e4040000-0000-4000-8000-000000000902', 'e4020000-0000-4000-8000-000000000009', 2, 'OPCION_UNICA', 'El pasaje cuesta S/ 45 por persona. ¿Cuánto pagan 4 personas?', 'Multiplicamos: 45 × 4 = S/ 180.', 1),
('e4040000-0000-4000-8000-000000001001', 'e4020000-0000-4000-8000-000000000010', 1, 'OPCION_UNICA', 'Una chacra rectangular mide 20 m de largo y 15 m de ancho. ¿Cuál es su perímetro?', 'El perímetro suma todos los lados: 20 + 15 + 20 + 15 = 70 m.', 1),
('e4040000-0000-4000-8000-000000001002', 'e4020000-0000-4000-8000-000000000010', 2, 'OPCION_UNICA', 'Con 3 kg de quinua se preparan 12 porciones. ¿Cuántas porciones salen con 5 kg?', 'Cada kilo rinde 12 ÷ 3 = 4 porciones; con 5 kg salen 5 × 4 = 20 porciones.', 1),
('e4040000-0000-4000-8000-000000001101', 'e4020000-0000-4000-8000-000000000011', 1, 'OPCION_UNICA', '¿Qué material usan los uros para construir sus islas?', 'El texto dice que los uros construyen islas flotantes con la totora.', 1),
('e4040000-0000-4000-8000-000000001102', 'e4020000-0000-4000-8000-000000000011', 2, 'OPCION_UNICA', '¿Qué podemos inferir sobre la totora?', 'Con la totora hacen islas, casas y botes; por eso inferimos que es muy importante para su vida.', 1),
('e4040000-0000-4000-8000-000000001201', 'e4020000-0000-4000-8000-000000000012', 1, 'OPCION_UNICA', '¿Qué tipo de texto es?', 'Empieza con un saludo («Querida prima») y termina con una despedida y la firma de Daniela.', 1),
('e4040000-0000-4000-8000-000000001202', 'e4020000-0000-4000-8000-000000000012', 2, 'OPCION_UNICA', '¿Por qué el guía pide no botar basura al río?', 'El guía explica que hay que cuidar el río «porque los delfines y los peces viven allí».', 1);
